d3=svg(arrow(90,80,235,80)+arrow(90,80,90,15)+text(155,68,'12 N')+text(42,25,'5 N')+'<circle cx="90" cy="80" r="4" fill="#203b43"/>',105,'Two perpendicular forces on a particle')
