d5=svg('<path d="M20 93H250" fill="none" stroke="#657c75"/><rect x="55" y="66" width="30" height="27" fill="#e9f3ee" stroke="#146d65"/>'+arrow(70,80,174,20)+text(185,23,'20 N')+text(100,79,'30°')+text(210,85,'5 kg'),105,'Five kilogram block pulled 30 degrees above horizontal')
