d8=svg('<path d="M45 80H225" fill="none" stroke="#a9b9b3" stroke-dasharray="3 3"/>'+arrow(135,80,67.45,41)+arrow(135,80,174,12)+arrow(135,80,135,116,'#9a6a29')+text(25,33,'left cable')+text(186,20,'right cable')+text(86,70,'30°')+text(169,69,'60°')+text(148,116,'100 N'),130,'Two cables supporting a 100 newton load')
