mechanics=[
q('A force is $(6\\mathbf i+8\\mathbf j)$ N. Find its magnitude and direction, measured above the positive horizontal axis.','10 N at 53.1° above the positive horizontal.',['The perpendicular components are 6 N horizontally and 8 N vertically.','Magnitude $=\\sqrt{6^2+8^2}=10$ N.','Both components are positive. The angle is $\\theta=\\tan^{-1}(\\tfrac86)=53.130\\ldots^\\circ$.'],rub(('M1','Uses the perpendicular components for magnitude'),('A1','Correct magnitude with unit'),('A1','Correct angle and quadrant'))),
q('Resolve a 20 N force at 30° above the horizontal into horizontal and vertical components.'+d2,'$10\\sqrt3$ N right; 10 N up.',['The horizontal component is adjacent to the angle: $20\\cos30^\\circ=10\\sqrt3$ N.','The vertical component is opposite: $20\\sin30^\\circ=10$ N. Both signs are positive.'],rub(('M1','Correct sine/cosine allocation'),('A1','Both components with directions and units'))),
q('A particle is in equilibrium under three forces. Two are 12 N right and 5 N up. Find the third force as a vector and give its magnitude.'+d3,'$(-12\\mathbf i-5\\mathbf j)$ N; magnitude 13 N.',['The two known forces sum to $(12\\mathbf i+5\\mathbf j)$ N.','Equilibrium means zero resultant, so the third force is their negative, $(-12\\mathbf i-5\\mathbf j)$ N.','Its magnitude is $\\sqrt{12^2+5^2}=13$ N.'],rub(('M1','Uses zero resultant'),('A1','Correct balancing vector'),('A1','Correct magnitude'))),
q('A 4 kg particle slides down a smooth plane inclined at 30°. Find its acceleration down the plane and the normal reaction.'+d4,'Acceleration 4.90 m s⁻² down the plane; $R=19.6\\sqrt3\\approx33.9$ N.',['Take down the slope as positive. Weight is $mg=4(9.8)=39.2$ N; smooth means no friction.','Parallel to the plane: $39.2\\sin30^\\circ=4a$, giving $a=4.9$ m s⁻².','Perpendicular to the plane there is no acceleration: $R=39.2\\cos30^\\circ=19.6\\sqrt3$ N.'],rub(('B1','Correct weight components and smooth-plane assumption'),('A1','Correct acceleration and direction'),('A1','Correct normal reaction'))),
q('A 5 kg particle on a smooth horizontal surface is pulled by 20 N at 30° above the horizontal. Find its acceleration and normal reaction.'+d5,'$a=2\\sqrt3\\approx3.46$ m s⁻² right; $R=39.0$ N.',['Horizontally, the driving component is $20\\cos30^\\circ=10\\sqrt3$ N.','Apply $F=ma$: $10\\sqrt3=5a$, so $a=2\\sqrt3$ m s⁻².','Vertically there is no acceleration: $R+20\\sin30^\\circ=5(9.8)$. Hence $R=49-10=39$ N.'],rub(('M1','Resolves the applied force correctly'),('A1','Correct horizontal acceleration'),('A1','Correct vertical balance and reaction'))),
q('Forces $(6\\mathbf i-2\\mathbf j)$ N and $(-2\\mathbf i+8\\mathbf j)$ N act on a 2 kg particle. Find its acceleration vector and acceleration magnitude.','$(2\\mathbf i+3\\mathbf j)$ m s⁻²; magnitude $\\sqrt{13}\\approx3.61$ m s⁻².',['Add the forces: $\\mathbf F=(4\\mathbf i+6\\mathbf j)$ N.','Use the vector equation $\\mathbf F=m\\mathbf a$: $\\mathbf a=\\tfrac12(4\\mathbf i+6\\mathbf j)=(2\\mathbf i+3\\mathbf j)$ m s⁻².','Magnitude $|\\mathbf a|=\\sqrt{2^2+3^2}=\\sqrt{13}$ m s⁻².'],rub(('M1','Correct resultant force'),('A1','Correct acceleration vector'),('A1','Correct acceleration magnitude with units'))),
q('A 3 kg particle moves right on a horizontal surface. A 20 N force acts 30° below the horizontal; a resistance of 8 N acts left. Find acceleration and normal reaction.'+d7,'$a=\\dfrac{10\\sqrt3-8}3\\approx3.11$ m s⁻² right; $R=39.4$ N.',['Resolve the applied force: $20\\cos30^\\circ=10\\sqrt3$ N right and $20\\sin30^\\circ=10$ N down.','Horizontally, $10\\sqrt3-8=3a$, so $a=\\dfrac{10\\sqrt3-8}3$ m s⁻².','Vertically, $R=3(9.8)+10=39.4$ N. The downward pull increases the reaction.'],rub(('M1','Correct downward and horizontal components'),('A1','Correct acceleration with resistance subtracted'),('A1','Correct increased normal reaction'))),
q('Two light cables support a 100 N load in equilibrium. The left cable makes 30° with the horizontal and the right makes 60°. Find both tensions.'+d8,'Left tension 50 N; right tension $50\\sqrt3\\approx86.6$ N.',['Let the tensions be L and R. Horizontally, $L\\cos30^\\circ=R\\cos60^\\circ$, so $R=\\sqrt3L$.','Vertically, $L\\sin30^\\circ+R\\sin60^\\circ=100$.','Substitute: $\\tfrac12L+(\\sqrt3L)(\\tfrac{\\sqrt3}2)=100$, so $2L=100$ and $L=50$ N.','Then $R=50\\sqrt3$ N. Substitution in both balance equations checks equilibrium.'],rub(('M1','Correct horizontal balance'),('M1','Correct vertical balance'),('A1','Correct left tension'),('A1','Correct right tension')))
]
